ValidationRule.errorConditionFormula:
AND(
   /* Applies to Account Support case record type only*/
   RecordTypeId = '0121a000000AXYM',
   ISPICKVAL( Status , "Closed"),
   ISCHANGED(Status),
   ISBLANK(ContactId),
   /* Flow will change checkbox if it needs to bypass this rule*/
   NOT(ISCHANGED(BypassCaseValidation__c ))
)
